<script setup lang="ts">
import {computed,ref} from 'vue'
import {ArrowRight,Download,Printer,Compass,NotebookPen,Check,Info} from 'lucide-vue-next'
import {date,labels,sections,download,type Report,type Topic} from './lib'
const props=defineProps<{report:Report;preview?:boolean}>();const emit=defineEmits<{upgrade:[report:Report]}>()
const active=ref('overview');const exporting=ref(false);const exportError=ref('');const includeAdvice=ref(false)
const tabs=computed(()=>[{id:'overview',label:'性格概览'},{id:'dimensions',label:'四维分析'},...(props.report.mode==='full'?[{id:'career',label:'职业发展'},{id:'social',label:'社交关系'},{id:'romance',label:'恋爱关系'}]:[]),{id:'growth',label:props.report.mode==='full'?'30 天行动':'7 天行动'}])
const topicGroups=computed(()=>['career','social','romance'].map(section=>({section,title:sections[section],topics:props.report.topics.filter(t=>t.section===section)})))
function preferred(t:Topic){return t.score===null?'信息不足':t.balanced?'两端接近':(t.score>50?t.right:t.left)}
function printReport(){window.print()}
async function exportImage(){
  exporting.value=true;exportError.value=''
  try{
    const canvas=document.createElement('canvas');canvas.width=1080;canvas.height=includeAdvice.value?1740:1150
    const ctx=canvas.getContext('2d');if(!ctx)throw new Error('当前浏览器不支持图片生成，请尝试保存 PDF。')
    ctx.fillStyle='#faf9f6';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.fillStyle='#28634e';ctx.fillRect(0,0,1080,16)
    let y=100;const wrap=(text:string,size:number,color='#253a31',line=40)=>{ctx.font=`${size}px "PingFang SC", "Microsoft YaHei", sans-serif`;ctx.fillStyle=color;let row='';for(const char of text){if(ctx.measureText(row+char).width>910){ctx.fillText(row,80,y);y+=line;row=''}row+=char}if(row){ctx.fillText(row,80,y);y+=line}}
    wrap('知序 · SELF ATLAS',28);y+=35;wrap(props.report.type,112,'#28634e',130);wrap(props.report.name,40);y+=24
    for(const d of props.report.dimensions){wrap(`${d.title}    ${d.left} ${d.score}% / ${d.right} ${(100-d.score).toFixed(1)}%`,25,'#526358',40);ctx.fillStyle='#dce1d7';ctx.fillRect(80,y,910,10);ctx.fillStyle='#28634e';ctx.fillRect(80,y,910*d.score/100,10);y+=62}
    if(includeAdvice.value){y+=12;wrap('给自己的三个小行动',30);for(const p of props.report.priorities){y+=10;wrap(p.title,24);wrap(p.text,22,'#526358',35)}}
    y=canvas.height-140;wrap('原创 MBTI 风格探索 · 非官方量表或心理诊断',22,'#6c786e',34);wrap('偏好位置不是准确率。性格是一张地图，每一步由你决定。',22,'#6c786e',34)
    const blob=await new Promise<Blob>((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(new Error('图片生成失败，请重试。')),'image/png'))
    download(`知序-${props.report.type}-人格摘要.png`,blob)
  }catch(e){exportError.value=(e as Error).message}finally{exporting.value=false}
}
</script>

<template>
 <div class="page report-page">
  <div class="report-meta"><span class="eyebrow">{{report.mode==='basic'?'精简版 · 99 题':'详细版 · 300 题'}}人格探索报告</span><span class="tag">{{preview?'报告预览 · 不保存到客户历史':date(report.createdAt)}}</span></div>
  <div class="report-hero"><div><span class="eyebrow">A SMALL ATLAS OF YOU</span><h1 class="serif">更了解自己，<br><span class="accent">也更接纳自己。</span></h1><p>{{report.type.includes('X')?'有些维度暂时没有明显倾向。先看看连续分数与具体情境，不必急着用一个类型定义自己。':report.dimensions.map(d=>d.observation).join('，')+'。这些是当前回答中的线索，可以结合真实生活继续核对。'}}</p><div class="tag-row"><span v-for="d in report.dimensions" :key="d.key" class="tag">{{d.letter==='X'?'尚无明显倾向':d.borderline?'接近均衡':d.observation}}</span></div></div><div class="type-seal"><span class="eyebrow">YOUR PERSONALITY</span><strong>{{report.type}}</strong><span>{{report.name}}</span><span class="seal-flower" aria-hidden="true">✳</span></div></div>
  <div class="alert report-notice"><Info :size="18"/><span>{{report.notice}} 数值表示偏好位置，不是能力或准确率。</span></div>
  <div v-if="report.warnings.length" class="report-warnings"><p v-for="warning in report.warnings" :key="warning">{{warning}}</p></div>
  <nav class="report-nav no-print" aria-label="报告章节"><button v-for="tab in tabs" :key="tab.id" :class="{active:active===tab.id}" :aria-pressed="active===tab.id" @click="active=tab.id">{{tab.label}}</button></nav>
  <section v-show="active==='overview'" class="report-section" data-report-section="overview"><div class="section-heading"><h2>最值得关注的三件事</h2><span class="eyebrow">FROM UNDERSTANDING TO ACTION</span></div><div class="priority-grid"><article v-for="(p,i) in report.priorities" :key="p.title" class="surface"><span class="eyebrow">0{{i+1}}</span><h3>{{p.title}}</h3><p>{{p.text}}</p><small>从一个可实践的小步骤开始，核对它是否适合你。</small></article></div><div class="overview-layout"><article class="surface prose-panel"><Compass :size="25" class="accent"/><h2 class="serif">性格是地图，<br>生活由你探索。</h2><p>{{report.template?.overview||'偏好描述习惯，不代表能力边界。'}}</p><p>{{report.template?.reflection||'请结合真实生活核对结果。'}}</p><template v-if="report.type.includes('X')"><h3>相邻类型参考</h3><div class="tag-row"><RouterLink v-for="code in report.candidates" :key="code" :to="`/types/${code}`" class="tag">{{code}}</RouterLink></div></template></article><div class="dimension-summary"><h3>四维偏好速览</h3><div v-for="d in report.dimensions" :key="d.key" class="mini-dimension"><div><span>{{d.title}}</span><strong>{{d.letter==='X'?'两端相同':`${Math.max(d.score,100-d.score).toFixed(1)}% ${d.letter}`}}</strong></div><div class="scale-track"><i :style="{width:`${d.score}%`}"></i></div><small>{{d.left}} {{d.score}}% / {{d.right}} {{(100-d.score).toFixed(1)}}%</small></div></div></div></section>
  <section v-show="active==='dimensions'" class="report-section" data-report-section="dimensions"><div class="section-heading"><h2>四维偏好，有深浅也有弹性</h2></div><p v-if="report.mode==='full'" class="muted">99 题基线 {{report.baselineType}}；本次扩展结果使用 120 道人格题，每维 30 题。三个专项分别分析。</p><article v-for="(d,i) in report.dimensions" :key="d.key" class="dimension-detail surface"><div class="panel-heading"><h3>{{d.title}}</h3><span class="tag">{{d.count}} 题 · {{d.borderline?'接近均衡':`倾向 ${d.letter}`}}</span></div><div class="scale-labels"><span>{{d.left}} {{d.score}}%</span><span>{{d.right}} {{(100-d.score).toFixed(1)}}%</span></div><div class="scale-track" role="img" :aria-label="`${d.left} ${d.score}%，${d.right} ${(100-d.score).toFixed(1)}%`"><i :style="{width:`${d.score}%`}"></i></div><p><strong>观察：</strong>{{d.observation}}。请核对这一描述在什么场景适合你。</p><p><strong>可能的优势：</strong>{{d.strength}}</p><p><strong>留意的盲点：</strong>{{d.blindspot}}</p><p><strong>生活情境：</strong>{{d.scenario}}</p><p><strong>尝试：</strong>{{d.advice}}</p><p v-if="report.mode==='full'" class="fineprint">99 题基线：{{report.baseline[i].left}} {{report.baseline[i].score}}% / {{report.baseline[i].right}} {{(100-report.baseline[i].score).toFixed(1)}}%。</p></article><p class="fineprint">45%–55% 标为接近均衡；该范围是解释规则，不是统计置信区间。恰好 50% 显示 X。</p></section>
  <template v-if="report.mode==='full'"><section v-for="group in topicGroups" :key="group.section" v-show="active===group.section" class="report-section" :data-report-section="group.section"><div class="section-heading"><h2>{{group.title}} · 让建议走进具体生活</h2></div><p class="muted">本章节依据专项 60 题，从 6 个观察主题展开。两端没有高低之分；请结合经历与现实条件核对。</p><div class="topic-grid"><article v-for="t in group.topics" :key="t.key" class="surface topic-card"><div class="panel-heading"><h3>{{t.title}}</h3><span class="tag">有效 {{t.valid}} / {{t.total}} 题</span></div><p class="topic-preference">{{preferred(t)}}</p><template v-if="t.score!==null"><div class="scale-labels"><span>{{t.left}}</span><span>{{t.right}}</span></div><div class="preference-track" role="img" :aria-label="`${t.title}偏好位置 ${t.score}，0 代表${t.left}，100 代表${t.right}`"><i :style="{left:`${t.score}%`}"></i></div></template><p class="observation"><strong>观察：</strong>{{t.observation}}。</p><details v-if="t.evidence.length" class="evidence"><summary>查看本次回答中的线索</summary><p v-for="item in t.evidence" :key="item.text">“{{item.text}}”<span>你的选择：{{labels[item.answer+3]}}</span></p></details><div class="advice-block"><span class="eyebrow">可以这样尝试</span><p>{{t.advice}}</p></div><p class="review-text"><strong>复盘：</strong>{{t.review}}</p></article></div><p class="fineprint">{{group.section==='career'?'职业探索还需要核对技能、资源、经验与机会，不能只由人格类型决定。':group.section==='romance'?'关系建议用于协商需要，不提供伴侣匹配分、关系结局预测或心理诊断。':'社交频率不等于关系质量；边界、投入与恢复都可以协商。'}}</p></section></template>
  <section v-show="active==='growth'" class="report-section" data-report-section="growth"><div class="section-heading"><h2>{{report.mode==='full'?'30 天成长计划':'7 天觉察与行动'}}</h2></div><div class="priority-grid"><article v-for="item in report.dailyAdvice" :key="item.title" class="surface"><h3>{{item.title}}</h3><p>{{item.text}}</p></article></div><article v-for="(step,i) in report.plan" :key="step.title" class="surface action-step"><span class="step-number">{{i+1}}</span><div><span class="eyebrow">{{report.mode==='full'?`第 ${i+1} 周`:'这 7 天'}}</span><h3>{{step.title}}</h3><p>{{step.task}}</p><p class="muted"><strong>复盘：</strong>{{step.review}}</p></div></article><div class="gentle-note"><NotebookPen :size="20"/><span>每天只做一个小调整。是否更适合真实生活，比是否符合某个类型更重要。</span></div></section>
  <section class="report-integrity"><p>问卷 {{report.version}} · 算法 {{report.algorithm}} · 模板 {{report.templateVersion||report.version}} · 已响应 {{report.coverage.answered}} 题 · 有效 {{report.coverage.valid}} 题 · 不适用 {{report.coverage.notApplicable}} 题。</p><p>本机保留一份报告副本；已提交的身份信息、答案和报告也会加密保存在管理员后台。清除浏览器数据只会删除本机副本。</p></section>
  <div class="report-export no-print"><div><h3>把理解留给自己</h3><p class="muted small">打印时选择“另存为 PDF”。摘要图片只包含类型与四维，可主动加入行动建议。</p><label class="check-row"><input type="checkbox" v-model="includeAdvice">在摘要图片中加入三个行动建议</label></div><div class="button-row"><button class="secondary" @click="printReport"><Printer :size="17"/>打印 / 保存 PDF</button><button class="secondary" :disabled="exporting" @click="exportImage"><Download :size="17"/>{{exporting?'正在生成…':'下载摘要图片'}}</button><button v-if="report.mode==='basic'&&!preview" class="primary" @click="emit('upgrade',report)">继续 300 题探索 <ArrowRight :size="17"/></button></div><p v-if="exportError" class="danger" role="alert">{{exportError}}</p></div>
 </div>
</template>
